window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7a1380b50e53b244"]={"versions": [{"id": "FIG-7a1380b50e53b244", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufs- und Scheduling-Diagramm (Ausführungs- und Präemptionsmodell auf der Zeitachse t).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des Ausführungsverhaltens, der zeitlichen Zerstückelung durch Präemption (Unterbrechung durch höherpriore Tasks/ISRs) und des Zusammenhangs zwischen Netto-Rechenzeit (Execution Time) und Brutto-Laufzeit (Response Time) der zyklischen Hauptfunktion <code>RamTst_MainFunction()</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li><strong>Schicht:</strong> Microcontroller Abstraction Layer (MCAL), Microcontroller Drivers (<code>RamTst</code>).\n</li><li><strong>Plattform:</strong> AUTOSAR Classic Platform (R4.2.2).\n</li><li><strong>Systemkontext:</strong> Der RAM-Test-Treiber führt im laufenden Steuergerätebetrieb nicht-destruktive Hintergrundprüfungen (z. B. March-Tests, Checkerboard, Walkpath) auf dem flüchtigen Speicher aus. Die Ausführung erfolgt scheduled über den BSW-Scheduler (<code>SchM</code>) bzw. das AUTOSAR OS im Kontext einer periodischen Task.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code>: Zyklische Schedulable Entity des MCAL-Moduls <code>RamTst</code>.\n</li><li><code>Basic Software Scheduler (SchM) / AUTOSAR OS</code>: Triggert <code>RamTst_MainFunction()</code> zyklisch an definierten Zeitpunkten (senkrechte Pfeile auf der Zeitachse).\n</li><li><code>Higher-Priority Tasks / ISRs</code>: Externe präemptierende Kontexte (Echtzeit-Tasks, Kommunikations-Treiber, Interrupt-Routinen), die <code>RamTst_MainFunction()</code> die CPU entziehen.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (ECU Configuration):</strong>\n<ul class=\"fig-list\"><li><code>RamTstNumberOfTestedCells</code>: Definiert die diskrete Anzahl an RAM-Zellen/Wörtern, die pro Aufruf von <code>RamTst_MainFunction()</code> getestet werden müssen.\n</li><li><code>RamTstAlgorithm</code>: Konfigurierter Prüfalgorithmus (z. B. <code>RAMTST_ALGORITHM_MARCH_C</code>, <code>RAMTST_ALGORITHM_WALKPATH</code>), der die Anzahl der Lese-/Schreibzugriffe pro Zelle (Operationskomplexität O(n)) und damit die Netto-Dauer bestimmt.\n</li></ul>\n</li><li><strong>Zustände &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Interner Iterationszeiger / Adresszeiger: Hält die aktuelle Testposition im RAM-Layout fest, um die Prüfung über aufeinanderfolgende Aufrufzyklen hinweg fortzusetzen.\n</li><li>Lokaler Puffer (Backup Buffer): Temporärer Speicher zur Sicherung der Originaldaten der aktuell getesteten Zellen bei nicht-destruktiven Testverfahren.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei Szenarien entlang der Zeitachse t gegenüber:</p>\n<ol class=\"fig-list\"><li><strong>Ununterbrochene Ausführung (Links – Idealfall / Baseline):</strong>\n<ul class=\"fig-list\"><li>Trigger: <code>SchM</code> ruft <code>RamTst_MainFunction()</code> auf.\n</li><li>Ablauf: Der Treiber testet kontinuierlich die durch <code>RamTstNumberOfTestedCells</code> festgelegte Anzahl an Speicherzellen mit dem konfigurierten Algorithmus.\n</li><li>Timing: Die Ausführungszeit entspricht exakt der reinen Netto-Rechenzeit (rosa Block) ohne Unterbrechung.\n</li><li>Rückkehr: Nach Erreichen der Zellgrenze kehrt die Funktion synchron zum Aufrufer zurück.\n</li></ul>\n</li><li><strong>Präemptive Zerstückelung (Mitte – Normaler Multitasking-Betrieb):</strong>\n<ul class=\"fig-list\"><li>Trigger: Periodischer Aufruf von <code>RamTst_MainFunction()</code>.\n</li><li>Ablauf: Während der Ausführung wird die Funktion mehrfach durch höherpriore Tasks oder ISRs verdrängt.\n</li><li>Timing-Aufteilung:\n<ul class=\"fig-list\"><li>Gestrichelter Kasten oben: Konstante kumulierte Netto-Ausführungszeit (Arbeitsbudget für <code>RamTstNumberOfTestedCells</code>).\n</li><li>Rosa Fragmente: Tatsächlich auf der CPU ausgeführte Test-Slices.\n</li><li>Lücken („Example of time [interrupted...]“): Zeiten, in denen höherpriore Tasks/ISRs die CPU belegen.\n</li></ul>\n</li><li>Konsequenz: Die Brutto-Verweildauer (Response Time) im Task-Zyklus verlängert sich drastisch gegenüber der Netto-Testzeit.\n</li></ul>\n</li><li><strong>Verzögerte Rückkehr bei hoher Systemlast (Rechts – Grenzfall-Scheduling):</strong>\n<ul class=\"fig-list\"><li>Ablauf: Starke Verdrängung zerlegt die Abarbeitung in viele kleine Ausführungsabschnitte.\n</li><li>Terminierung: <code>RamTst_MainFunction()</code> kehrt erst nach vollständiger Prüfung aller <code>RamTstNumberOfTestedCells</code> zurück („returns...“). Der zugewiesene Task-Kontext bleibt bis zur Fertigstellung aktiv, was bei unzureichendem Periodenbudget zu Task-Overruns führt.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dimensionierung von <code>RamTstNumberOfTestedCells</code>:</strong>\n<ul class=\"fig-list\"><li>Der Parameter ist direkt an das WCET-Budget (Worst-Case Execution Time) der Träger-Task gekoppelt. \n</li><li>Entwickler müssen <code>RamTstNumberOfTestedCells</code> anhand der algorithmischen Komplexität (n-fache Lese-/Schreibzugriffe) und der CPU-Taktfrequenz so kalibrieren, dass die maximale Netto-Laufzeit zuzüglich aller maximalen Präemptionszeiten die OS-Task-Deadline strikt unterschreitet.\n</li></ul>\n</li><li><strong>Task-Priorisierung &amp; Scheduling-Strategie:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code> gehört normativ in eine <strong>niedrigpriore Task</strong> (Background- oder Idle-Ebene). Eine zu hohe Priorität führt durch den zyklischen Speicherzugriff zu Jitter und Blocking bei zeitkritischen Regelungs- oder Kommunikations-Stacks (CAN, FlexRay, Ethernet).\n</li></ul>\n</li><li><strong>Datenkonsistenz &amp; Nicht-Destruktivität:</strong>\n<ul class=\"fig-list\"><li>Da höherpriore Tasks den RAM-Test jederzeit unterbrechen können, dürfen die aktuell getesteten Speicherzellen nicht durch externe Zugriffe korrumpiert werden. \n</li><li>Der Treiber muss entweder nicht-destruktiv mit atomaren Schreib-/Lesezyklen und Zwischenpuffern arbeiten oder es dürfen nur solche RAM-Bereiche zur Laufzeit getestet werden, die während der Testphase gegen gleichzeitige Schreibzugriffe höherpriorer Tasks geschützt sind (Buffer Exclusion / Task Synchronisation).\n</li></ul>\n</li><li><strong>Gesamtumlaufzeit (RAM Coverage Cycle):</strong>\n<ul class=\"fig-list\"><li>Die Gesamtdauer für einen vollständigen Test des gesamten RAM-Bereichs berechnet sich aus:\n $$T_{\\text{Gesamttest}} = \\left\\lceil \\frac{\\text{Gesamtzahl zu prüfender Zellen}}{\\text{RamTstNumberOfTestedCells}} \\right\\rceil \\times T_{\\text{Task-Periode}}$$\n</li><li>Eine Reduktion der Blockgröße pro Aufruf zur Vermeidung von Task-Overruns verlängert unmittelbar die Diagnosezeit bis zur Fehlererkennung (Fault Detection Time Interval, FDTI nach ISO 26262).\n</li></ul>\n</li></ul>"}, {"id": "FIG-aaa625bb82f04a03", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufs- und Scheduling-Diagramm (Ausführungs- und Präemptionsmodell auf der Zeitachse t).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des Ausführungsverhaltens, der zeitlichen Zerstückelung durch Präemption (Unterbrechung durch höherpriore Tasks/ISRs) und des Zusammenhangs zwischen Netto-Rechenzeit (Execution Time) und Brutto-Laufzeit (Response Time) der zyklischen Hauptfunktion <code>RamTst_MainFunction()</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li><strong>Schicht:</strong> Microcontroller Abstraction Layer (MCAL), Microcontroller Drivers (<code>RamTst</code>).\n</li><li><strong>Plattform:</strong> AUTOSAR Classic Platform (R4.2.2).\n</li><li><strong>Systemkontext:</strong> Der RAM-Test-Treiber führt im laufenden Steuergerätebetrieb nicht-destruktive Hintergrundprüfungen (z. B. March-Tests, Checkerboard, Walkpath) auf dem flüchtigen Speicher aus. Die Ausführung erfolgt scheduled über den BSW-Scheduler (<code>SchM</code>) bzw. das AUTOSAR OS im Kontext einer periodischen Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code>: Zyklische Schedulable Entity des MCAL-Moduls <code>RamTst</code>.\n</li><li><code>Basic Software Scheduler (SchM) / AUTOSAR OS</code>: Triggert <code>RamTst_MainFunction()</code> zyklisch an definierten Zeitpunkten (senkrechte Pfeile auf der Zeitachse).\n</li><li><code>Higher-Priority Tasks / ISRs</code>: Externe präemptierende Kontexte (Echtzeit-Tasks, Kommunikations-Treiber, Interrupt-Routinen), die <code>RamTst_MainFunction()</code> die CPU entziehen.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (ECU Configuration):</strong>\n<ul class=\"fig-list\"><li><code>RamTstNumberOfTestedCells</code>: Definiert die diskrete Anzahl an RAM-Zellen/Wörtern, die pro Aufruf von <code>RamTst_MainFunction()</code> getestet werden müssen.\n</li><li><code>RamTstAlgorithm</code>: Konfigurierter Prüfalgorithmus (z. B. <code>RAMTST_ALGORITHM_MARCH_C</code>, <code>RAMTST_ALGORITHM_WALKPATH</code>), der die Anzahl der Lese-/Schreibzugriffe pro Zelle (Operationskomplexität O(n)) und damit die Netto-Dauer bestimmt.\n</li></ul>\n</li><li><strong>Zustände &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Interner Iterationszeiger / Adresszeiger: Hält die aktuelle Testposition im RAM-Layout fest, um die Prüfung über aufeinanderfolgende Aufrufzyklen hinweg fortzusetzen.\n</li><li>Lokaler Puffer (Backup Buffer): Temporärer Speicher zur Sicherung der Originaldaten der aktuell getesteten Zellen bei nicht-destruktiven Testverfahren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei Szenarien entlang der Zeitachse t gegenüber:</p>\n<ol class=\"fig-list\"><li><strong>Ununterbrochene Ausführung (Links – Idealfall / Baseline):</strong>\n<ul class=\"fig-list\"><li>Trigger: <code>SchM</code> ruft <code>RamTst_MainFunction()</code> auf.\n</li><li>Ablauf: Der Treiber testet kontinuierlich die durch <code>RamTstNumberOfTestedCells</code> festgelegte Anzahl an Speicherzellen mit dem konfigurierten Algorithmus.\n</li><li>Timing: Die Ausführungszeit entspricht exakt der reinen Netto-Rechenzeit (rosa Block) ohne Unterbrechung.\n</li><li>Rückkehr: Nach Erreichen der Zellgrenze kehrt die Funktion synchron zum Aufrufer zurück.\n</li></ul>\n</li><li><strong>Präemptive Zerstückelung (Mitte – Normaler Multitasking-Betrieb):</strong>\n<ul class=\"fig-list\"><li>Trigger: Periodischer Aufruf von <code>RamTst_MainFunction()</code>.\n</li><li>Ablauf: Während der Ausführung wird die Funktion mehrfach durch höherpriore Tasks oder ISRs verdrängt.\n</li><li>Timing-Aufteilung:\n<ul class=\"fig-list\"><li>Gestrichelter Kasten oben: Konstante kumulierte Netto-Ausführungszeit (Arbeitsbudget für <code>RamTstNumberOfTestedCells</code>).\n</li><li>Rosa Fragmente: Tatsächlich auf der CPU ausgeführte Test-Slices.\n</li><li>Lücken („Example of time [interrupted...]“): Zeiten, in denen höherpriore Tasks/ISRs die CPU belegen.\n</li></ul>\n</li><li>Konsequenz: Die Brutto-Verweildauer (Response Time) im Task-Zyklus verlängert sich drastisch gegenüber der Netto-Testzeit.\n</li></ul>\n</li><li><strong>Verzögerte Rückkehr bei hoher Systemlast (Rechts – Grenzfall-Scheduling):</strong>\n<ul class=\"fig-list\"><li>Ablauf: Starke Verdrängung zerlegt die Abarbeitung in viele kleine Ausführungsabschnitte.\n</li><li>Terminierung: <code>RamTst_MainFunction()</code> kehrt erst nach vollständiger Prüfung aller <code>RamTstNumberOfTestedCells</code> zurück („returns...“). Der zugewiesene Task-Kontext bleibt bis zur Fertigstellung aktiv, was bei unzureichendem Periodenbudget zu Task-Overruns führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dimensionierung von <code>RamTstNumberOfTestedCells</code>:</strong>\n<ul class=\"fig-list\"><li>Der Parameter ist direkt an das WCET-Budget (Worst-Case Execution Time) der Träger-Task gekoppelt. \n</li><li>Entwickler müssen <code>RamTstNumberOfTestedCells</code> anhand der algorithmischen Komplexität (n-fache Lese-/Schreibzugriffe) und der CPU-Taktfrequenz so kalibrieren, dass die maximale Netto-Laufzeit zuzüglich aller maximalen Präemptionszeiten die OS-Task-Deadline strikt unterschreitet.\n</li></ul>\n</li><li><strong>Task-Priorisierung &amp; Scheduling-Strategie:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code> gehört normativ in eine <strong>niedrigpriore Task</strong> (Background- oder Idle-Ebene). Eine zu hohe Priorität führt durch den zyklischen Speicherzugriff zu Jitter und Blocking bei zeitkritischen Regelungs- oder Kommunikations-Stacks (CAN, FlexRay, Ethernet).\n</li></ul>\n</li><li><strong>Datenkonsistenz &amp; Nicht-Destruktivität:</strong>\n<ul class=\"fig-list\"><li>Da höherpriore Tasks den RAM-Test jederzeit unterbrechen können, dürfen die aktuell getesteten Speicherzellen nicht durch externe Zugriffe korrumpiert werden. \n</li><li>Der Treiber muss entweder nicht-destruktiv mit atomaren Schreib-/Lesezyklen und Zwischenpuffern arbeiten oder es dürfen nur solche RAM-Bereiche zur Laufzeit getestet werden, die während der Testphase gegen gleichzeitige Schreibzugriffe höherpriorer Tasks geschützt sind (Buffer Exclusion / Task Synchronisation).\n</li></ul>\n</li><li><strong>Gesamtumlaufzeit (RAM Coverage Cycle):</strong>\n<ul class=\"fig-list\"><li>Die Gesamtdauer für einen vollständigen Test des gesamten RAM-Bereichs berechnet sich aus:\n $$T_{\\text{Gesamttest}} = \\left\\lceil \\frac{\\text{Gesamtzahl zu prüfender Zellen}}{\\text{RamTstNumberOfTestedCells}} \\right\\rceil \\times T_{\\text{Task-Periode}}$$\n</li><li>Eine Reduktion der Blockgröße pro Aufruf zur Vermeidung von Task-Overruns verlängert unmittelbar die Diagnosezeit bis zur Fehlererkennung (Fault Detection Time Interval, FDTI nach ISO 26262).\n</li></ul>\n</li></ul>"}, {"id": "FIG-7f8a559327475c1a", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufs- und Scheduling-Diagramm (Ausführungs- und Präemptionsmodell auf der Zeitachse t).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des Ausführungsverhaltens, der zeitlichen Zerstückelung durch Präemption (Unterbrechung durch höherpriore Tasks/ISRs) und des Zusammenhangs zwischen Netto-Rechenzeit (Execution Time) und Brutto-Laufzeit (Response Time) der zyklischen Hauptfunktion <code>RamTst_MainFunction()</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li><strong>Schicht:</strong> Microcontroller Abstraction Layer (MCAL), Microcontroller Drivers (<code>RamTst</code>).\n</li><li><strong>Plattform:</strong> AUTOSAR Classic Platform (R4.2.2).\n</li><li><strong>Systemkontext:</strong> Der RAM-Test-Treiber führt im laufenden Steuergerätebetrieb nicht-destruktive Hintergrundprüfungen (z. B. March-Tests, Checkerboard, Walkpath) auf dem flüchtigen Speicher aus. Die Ausführung erfolgt scheduled über den BSW-Scheduler (<code>SchM</code>) bzw. das AUTOSAR OS im Kontext einer periodischen Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code>: Zyklische Schedulable Entity des MCAL-Moduls <code>RamTst</code>.\n</li><li><code>Basic Software Scheduler (SchM) / AUTOSAR OS</code>: Triggert <code>RamTst_MainFunction()</code> zyklisch an definierten Zeitpunkten (senkrechte Pfeile auf der Zeitachse).\n</li><li><code>Higher-Priority Tasks / ISRs</code>: Externe präemptierende Kontexte (Echtzeit-Tasks, Kommunikations-Treiber, Interrupt-Routinen), die <code>RamTst_MainFunction()</code> die CPU entziehen.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (ECU Configuration):</strong>\n<ul class=\"fig-list\"><li><code>RamTstNumberOfTestedCells</code>: Definiert die diskrete Anzahl an RAM-Zellen/Wörtern, die pro Aufruf von <code>RamTst_MainFunction()</code> getestet werden müssen.\n</li><li><code>RamTstAlgorithm</code>: Konfigurierter Prüfalgorithmus (z. B. <code>RAMTST_ALGORITHM_MARCH_C</code>, <code>RAMTST_ALGORITHM_WALKPATH</code>), der die Anzahl der Lese-/Schreibzugriffe pro Zelle (Operationskomplexität O(n)) und damit die Netto-Dauer bestimmt.\n</li></ul>\n</li><li><strong>Zustände &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Interner Iterationszeiger / Adresszeiger: Hält die aktuelle Testposition im RAM-Layout fest, um die Prüfung über aufeinanderfolgende Aufrufzyklen hinweg fortzusetzen.\n</li><li>Lokaler Puffer (Backup Buffer): Temporärer Speicher zur Sicherung der Originaldaten der aktuell getesteten Zellen bei nicht-destruktiven Testverfahren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei Szenarien entlang der Zeitachse t gegenüber:</p>\n<ol class=\"fig-list\"><li><strong>Ununterbrochene Ausführung (Links – Idealfall / Baseline):</strong>\n<ul class=\"fig-list\"><li>Trigger: <code>SchM</code> ruft <code>RamTst_MainFunction()</code> auf.\n</li><li>Ablauf: Der Treiber testet kontinuierlich die durch <code>RamTstNumberOfTestedCells</code> festgelegte Anzahl an Speicherzellen mit dem konfigurierten Algorithmus.\n</li><li>Timing: Die Ausführungszeit entspricht exakt der reinen Netto-Rechenzeit (rosa Block) ohne Unterbrechung.\n</li><li>Rückkehr: Nach Erreichen der Zellgrenze kehrt die Funktion synchron zum Aufrufer zurück.\n</li></ul>\n</li><li><strong>Präemptive Zerstückelung (Mitte – Normaler Multitasking-Betrieb):</strong>\n<ul class=\"fig-list\"><li>Trigger: Periodischer Aufruf von <code>RamTst_MainFunction()</code>.\n</li><li>Ablauf: Während der Ausführung wird die Funktion mehrfach durch höherpriore Tasks oder ISRs verdrängt.\n</li><li>Timing-Aufteilung:\n<ul class=\"fig-list\"><li>Gestrichelter Kasten oben: Konstante kumulierte Netto-Ausführungszeit (Arbeitsbudget für <code>RamTstNumberOfTestedCells</code>).\n</li><li>Rosa Fragmente: Tatsächlich auf der CPU ausgeführte Test-Slices.\n</li><li>Lücken („Example of time [interrupted...]“): Zeiten, in denen höherpriore Tasks/ISRs die CPU belegen.\n</li></ul>\n</li><li>Konsequenz: Die Brutto-Verweildauer (Response Time) im Task-Zyklus verlängert sich drastisch gegenüber der Netto-Testzeit.\n</li></ul>\n</li><li><strong>Verzögerte Rückkehr bei hoher Systemlast (Rechts – Grenzfall-Scheduling):</strong>\n<ul class=\"fig-list\"><li>Ablauf: Starke Verdrängung zerlegt die Abarbeitung in viele kleine Ausführungsabschnitte.\n</li><li>Terminierung: <code>RamTst_MainFunction()</code> kehrt erst nach vollständiger Prüfung aller <code>RamTstNumberOfTestedCells</code> zurück („returns...“). Der zugewiesene Task-Kontext bleibt bis zur Fertigstellung aktiv, was bei unzureichendem Periodenbudget zu Task-Overruns führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dimensionierung von <code>RamTstNumberOfTestedCells</code>:</strong>\n<ul class=\"fig-list\"><li>Der Parameter ist direkt an das WCET-Budget (Worst-Case Execution Time) der Träger-Task gekoppelt. \n</li><li>Entwickler müssen <code>RamTstNumberOfTestedCells</code> anhand der algorithmischen Komplexität (n-fache Lese-/Schreibzugriffe) und der CPU-Taktfrequenz so kalibrieren, dass die maximale Netto-Laufzeit zuzüglich aller maximalen Präemptionszeiten die OS-Task-Deadline strikt unterschreitet.\n</li></ul>\n</li><li><strong>Task-Priorisierung &amp; Scheduling-Strategie:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code> gehört normativ in eine <strong>niedrigpriore Task</strong> (Background- oder Idle-Ebene). Eine zu hohe Priorität führt durch den zyklischen Speicherzugriff zu Jitter und Blocking bei zeitkritischen Regelungs- oder Kommunikations-Stacks (CAN, FlexRay, Ethernet).\n</li></ul>\n</li><li><strong>Datenkonsistenz &amp; Nicht-Destruktivität:</strong>\n<ul class=\"fig-list\"><li>Da höherpriore Tasks den RAM-Test jederzeit unterbrechen können, dürfen die aktuell getesteten Speicherzellen nicht durch externe Zugriffe korrumpiert werden. \n</li><li>Der Treiber muss entweder nicht-destruktiv mit atomaren Schreib-/Lesezyklen und Zwischenpuffern arbeiten oder es dürfen nur solche RAM-Bereiche zur Laufzeit getestet werden, die während der Testphase gegen gleichzeitige Schreibzugriffe höherpriorer Tasks geschützt sind (Buffer Exclusion / Task Synchronisation).\n</li></ul>\n</li><li><strong>Gesamtumlaufzeit (RAM Coverage Cycle):</strong>\n<ul class=\"fig-list\"><li>Die Gesamtdauer für einen vollständigen Test des gesamten RAM-Bereichs berechnet sich aus:\n $$T_{\\text{Gesamttest}} = \\left\\lceil \\frac{\\text{Gesamtzahl zu prüfender Zellen}}{\\text{RamTstNumberOfTestedCells}} \\right\\rceil \\times T_{\\text{Task-Periode}}$$\n</li><li>Eine Reduktion der Blockgröße pro Aufruf zur Vermeidung von Task-Overruns verlängert unmittelbar die Diagnosezeit bis zur Fehlererkennung (Fault Detection Time Interval, FDTI nach ISO 26262).\n</li></ul>\n</li></ul>"}, {"id": "FIG-67d8da68f53e0475", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufs- und Scheduling-Diagramm (Ausführungs- und Präemptionsmodell auf der Zeitachse t).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des Ausführungsverhaltens, der zeitlichen Zerstückelung durch Präemption (Unterbrechung durch höherpriore Tasks/ISRs) und des Zusammenhangs zwischen Netto-Rechenzeit (Execution Time) und Brutto-Laufzeit (Response Time) der zyklischen Hauptfunktion <code>RamTst_MainFunction()</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li><strong>Schicht:</strong> Microcontroller Abstraction Layer (MCAL), Microcontroller Drivers (<code>RamTst</code>).\n</li><li><strong>Plattform:</strong> AUTOSAR Classic Platform (R4.2.2).\n</li><li><strong>Systemkontext:</strong> Der RAM-Test-Treiber führt im laufenden Steuergerätebetrieb nicht-destruktive Hintergrundprüfungen (z. B. March-Tests, Checkerboard, Walkpath) auf dem flüchtigen Speicher aus. Die Ausführung erfolgt scheduled über den BSW-Scheduler (<code>SchM</code>) bzw. das AUTOSAR OS im Kontext einer periodischen Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code>: Zyklische Schedulable Entity des MCAL-Moduls <code>RamTst</code>.\n</li><li><code>Basic Software Scheduler (SchM) / AUTOSAR OS</code>: Triggert <code>RamTst_MainFunction()</code> zyklisch an definierten Zeitpunkten (senkrechte Pfeile auf der Zeitachse).\n</li><li><code>Higher-Priority Tasks / ISRs</code>: Externe präemptierende Kontexte (Echtzeit-Tasks, Kommunikations-Treiber, Interrupt-Routinen), die <code>RamTst_MainFunction()</code> die CPU entziehen.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (ECU Configuration):</strong>\n<ul class=\"fig-list\"><li><code>RamTstNumberOfTestedCells</code>: Definiert die diskrete Anzahl an RAM-Zellen/Wörtern, die pro Aufruf von <code>RamTst_MainFunction()</code> getestet werden müssen.\n</li><li><code>RamTstAlgorithm</code>: Konfigurierter Prüfalgorithmus (z. B. <code>RAMTST_ALGORITHM_MARCH_C</code>, <code>RAMTST_ALGORITHM_WALKPATH</code>), der die Anzahl der Lese-/Schreibzugriffe pro Zelle (Operationskomplexität O(n)) und damit die Netto-Dauer bestimmt.\n</li></ul>\n</li><li><strong>Zustände &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Interner Iterationszeiger / Adresszeiger: Hält die aktuelle Testposition im RAM-Layout fest, um die Prüfung über aufeinanderfolgende Aufrufzyklen hinweg fortzusetzen.\n</li><li>Lokaler Puffer (Backup Buffer): Temporärer Speicher zur Sicherung der Originaldaten der aktuell getesteten Zellen bei nicht-destruktiven Testverfahren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei Szenarien entlang der Zeitachse t gegenüber:</p>\n<ol class=\"fig-list\"><li><strong>Ununterbrochene Ausführung (Links – Idealfall / Baseline):</strong>\n<ul class=\"fig-list\"><li>Trigger: <code>SchM</code> ruft <code>RamTst_MainFunction()</code> auf.\n</li><li>Ablauf: Der Treiber testet kontinuierlich die durch <code>RamTstNumberOfTestedCells</code> festgelegte Anzahl an Speicherzellen mit dem konfigurierten Algorithmus.\n</li><li>Timing: Die Ausführungszeit entspricht exakt der reinen Netto-Rechenzeit (rosa Block) ohne Unterbrechung.\n</li><li>Rückkehr: Nach Erreichen der Zellgrenze kehrt die Funktion synchron zum Aufrufer zurück.\n</li></ul>\n</li><li><strong>Präemptive Zerstückelung (Mitte – Normaler Multitasking-Betrieb):</strong>\n<ul class=\"fig-list\"><li>Trigger: Periodischer Aufruf von <code>RamTst_MainFunction()</code>.\n</li><li>Ablauf: Während der Ausführung wird die Funktion mehrfach durch höherpriore Tasks oder ISRs verdrängt.\n</li><li>Timing-Aufteilung:\n<ul class=\"fig-list\"><li>Gestrichelter Kasten oben: Konstante kumulierte Netto-Ausführungszeit (Arbeitsbudget für <code>RamTstNumberOfTestedCells</code>).\n</li><li>Rosa Fragmente: Tatsächlich auf der CPU ausgeführte Test-Slices.\n</li><li>Lücken („Example of time [interrupted...]“): Zeiten, in denen höherpriore Tasks/ISRs die CPU belegen.\n</li></ul>\n</li><li>Konsequenz: Die Brutto-Verweildauer (Response Time) im Task-Zyklus verlängert sich drastisch gegenüber der Netto-Testzeit.\n</li></ul>\n</li><li><strong>Verzögerte Rückkehr bei hoher Systemlast (Rechts – Grenzfall-Scheduling):</strong>\n<ul class=\"fig-list\"><li>Ablauf: Starke Verdrängung zerlegt die Abarbeitung in viele kleine Ausführungsabschnitte.\n</li><li>Terminierung: <code>RamTst_MainFunction()</code> kehrt erst nach vollständiger Prüfung aller <code>RamTstNumberOfTestedCells</code> zurück („returns...“). Der zugewiesene Task-Kontext bleibt bis zur Fertigstellung aktiv, was bei unzureichendem Periodenbudget zu Task-Overruns führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dimensionierung von <code>RamTstNumberOfTestedCells</code>:</strong>\n<ul class=\"fig-list\"><li>Der Parameter ist direkt an das WCET-Budget (Worst-Case Execution Time) der Träger-Task gekoppelt. \n</li><li>Entwickler müssen <code>RamTstNumberOfTestedCells</code> anhand der algorithmischen Komplexität (n-fache Lese-/Schreibzugriffe) und der CPU-Taktfrequenz so kalibrieren, dass die maximale Netto-Laufzeit zuzüglich aller maximalen Präemptionszeiten die OS-Task-Deadline strikt unterschreitet.\n</li></ul>\n</li><li><strong>Task-Priorisierung &amp; Scheduling-Strategie:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code> gehört normativ in eine <strong>niedrigpriore Task</strong> (Background- oder Idle-Ebene). Eine zu hohe Priorität führt durch den zyklischen Speicherzugriff zu Jitter und Blocking bei zeitkritischen Regelungs- oder Kommunikations-Stacks (CAN, FlexRay, Ethernet).\n</li></ul>\n</li><li><strong>Datenkonsistenz &amp; Nicht-Destruktivität:</strong>\n<ul class=\"fig-list\"><li>Da höherpriore Tasks den RAM-Test jederzeit unterbrechen können, dürfen die aktuell getesteten Speicherzellen nicht durch externe Zugriffe korrumpiert werden. \n</li><li>Der Treiber muss entweder nicht-destruktiv mit atomaren Schreib-/Lesezyklen und Zwischenpuffern arbeiten oder es dürfen nur solche RAM-Bereiche zur Laufzeit getestet werden, die während der Testphase gegen gleichzeitige Schreibzugriffe höherpriorer Tasks geschützt sind (Buffer Exclusion / Task Synchronisation).\n</li></ul>\n</li><li><strong>Gesamtumlaufzeit (RAM Coverage Cycle):</strong>\n<ul class=\"fig-list\"><li>Die Gesamtdauer für einen vollständigen Test des gesamten RAM-Bereichs berechnet sich aus:\n $$T_{\\text{Gesamttest}} = \\left\\lceil \\frac{\\text{Gesamtzahl zu prüfender Zellen}}{\\text{RamTstNumberOfTestedCells}} \\right\\rceil \\times T_{\\text{Task-Periode}}$$\n</li><li>Eine Reduktion der Blockgröße pro Aufruf zur Vermeidung von Task-Overruns verlängert unmittelbar die Diagnosezeit bis zur Fehlererkennung (Fault Detection Time Interval, FDTI nach ISO 26262).\n</li></ul>\n</li></ul>"}, {"id": "FIG-1454d20ef35d834e", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufs- und Scheduling-Diagramm (Ausführungs- und Präemptionsmodell auf der Zeitachse t).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des Ausführungsverhaltens, der zeitlichen Zerstückelung durch Präemption (Unterbrechung durch höherpriore Tasks/ISRs) und des Zusammenhangs zwischen Netto-Rechenzeit (Execution Time) und Brutto-Laufzeit (Response Time) der zyklischen Hauptfunktion <code>RamTst_MainFunction()</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li><strong>Schicht:</strong> Microcontroller Abstraction Layer (MCAL), Microcontroller Drivers (<code>RamTst</code>).\n</li><li><strong>Plattform:</strong> AUTOSAR Classic Platform (R4.2.2).\n</li><li><strong>Systemkontext:</strong> Der RAM-Test-Treiber führt im laufenden Steuergerätebetrieb nicht-destruktive Hintergrundprüfungen (z. B. March-Tests, Checkerboard, Walkpath) auf dem flüchtigen Speicher aus. Die Ausführung erfolgt scheduled über den BSW-Scheduler (<code>SchM</code>) bzw. das AUTOSAR OS im Kontext einer periodischen Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code>: Zyklische Schedulable Entity des MCAL-Moduls <code>RamTst</code>.\n</li><li><code>Basic Software Scheduler (SchM) / AUTOSAR OS</code>: Triggert <code>RamTst_MainFunction()</code> zyklisch an definierten Zeitpunkten (senkrechte Pfeile auf der Zeitachse).\n</li><li><code>Higher-Priority Tasks / ISRs</code>: Externe präemptierende Kontexte (Echtzeit-Tasks, Kommunikations-Treiber, Interrupt-Routinen), die <code>RamTst_MainFunction()</code> die CPU entziehen.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (ECU Configuration):</strong>\n<ul class=\"fig-list\"><li><code>RamTstNumberOfTestedCells</code>: Definiert die diskrete Anzahl an RAM-Zellen/Wörtern, die pro Aufruf von <code>RamTst_MainFunction()</code> getestet werden müssen.\n</li><li><code>RamTstAlgorithm</code>: Konfigurierter Prüfalgorithmus (z. B. <code>RAMTST_ALGORITHM_MARCH_C</code>, <code>RAMTST_ALGORITHM_WALKPATH</code>), der die Anzahl der Lese-/Schreibzugriffe pro Zelle (Operationskomplexität O(n)) und damit die Netto-Dauer bestimmt.\n</li></ul>\n</li><li><strong>Zustände &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Interner Iterationszeiger / Adresszeiger: Hält die aktuelle Testposition im RAM-Layout fest, um die Prüfung über aufeinanderfolgende Aufrufzyklen hinweg fortzusetzen.\n</li><li>Lokaler Puffer (Backup Buffer): Temporärer Speicher zur Sicherung der Originaldaten der aktuell getesteten Zellen bei nicht-destruktiven Testverfahren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei Szenarien entlang der Zeitachse t gegenüber:</p>\n<ol class=\"fig-list\"><li><strong>Ununterbrochene Ausführung (Links – Idealfall / Baseline):</strong>\n<ul class=\"fig-list\"><li>Trigger: <code>SchM</code> ruft <code>RamTst_MainFunction()</code> auf.\n</li><li>Ablauf: Der Treiber testet kontinuierlich die durch <code>RamTstNumberOfTestedCells</code> festgelegte Anzahl an Speicherzellen mit dem konfigurierten Algorithmus.\n</li><li>Timing: Die Ausführungszeit entspricht exakt der reinen Netto-Rechenzeit (rosa Block) ohne Unterbrechung.\n</li><li>Rückkehr: Nach Erreichen der Zellgrenze kehrt die Funktion synchron zum Aufrufer zurück.\n</li></ul>\n</li><li><strong>Präemptive Zerstückelung (Mitte – Normaler Multitasking-Betrieb):</strong>\n<ul class=\"fig-list\"><li>Trigger: Periodischer Aufruf von <code>RamTst_MainFunction()</code>.\n</li><li>Ablauf: Während der Ausführung wird die Funktion mehrfach durch höherpriore Tasks oder ISRs verdrängt.\n</li><li>Timing-Aufteilung:\n<ul class=\"fig-list\"><li>Gestrichelter Kasten oben: Konstante kumulierte Netto-Ausführungszeit (Arbeitsbudget für <code>RamTstNumberOfTestedCells</code>).\n</li><li>Rosa Fragmente: Tatsächlich auf der CPU ausgeführte Test-Slices.\n</li><li>Lücken („Example of time [interrupted...]“): Zeiten, in denen höherpriore Tasks/ISRs die CPU belegen.\n</li></ul>\n</li><li>Konsequenz: Die Brutto-Verweildauer (Response Time) im Task-Zyklus verlängert sich drastisch gegenüber der Netto-Testzeit.\n</li></ul>\n</li><li><strong>Verzögerte Rückkehr bei hoher Systemlast (Rechts – Grenzfall-Scheduling):</strong>\n<ul class=\"fig-list\"><li>Ablauf: Starke Verdrängung zerlegt die Abarbeitung in viele kleine Ausführungsabschnitte.\n</li><li>Terminierung: <code>RamTst_MainFunction()</code> kehrt erst nach vollständiger Prüfung aller <code>RamTstNumberOfTestedCells</code> zurück („returns...“). Der zugewiesene Task-Kontext bleibt bis zur Fertigstellung aktiv, was bei unzureichendem Periodenbudget zu Task-Overruns führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dimensionierung von <code>RamTstNumberOfTestedCells</code>:</strong>\n<ul class=\"fig-list\"><li>Der Parameter ist direkt an das WCET-Budget (Worst-Case Execution Time) der Träger-Task gekoppelt. \n</li><li>Entwickler müssen <code>RamTstNumberOfTestedCells</code> anhand der algorithmischen Komplexität (n-fache Lese-/Schreibzugriffe) und der CPU-Taktfrequenz so kalibrieren, dass die maximale Netto-Laufzeit zuzüglich aller maximalen Präemptionszeiten die OS-Task-Deadline strikt unterschreitet.\n</li></ul>\n</li><li><strong>Task-Priorisierung &amp; Scheduling-Strategie:</strong>\n<ul class=\"fig-list\"><li><code>RamTst_MainFunction()</code> gehört normativ in eine <strong>niedrigpriore Task</strong> (Background- oder Idle-Ebene). Eine zu hohe Priorität führt durch den zyklischen Speicherzugriff zu Jitter und Blocking bei zeitkritischen Regelungs- oder Kommunikations-Stacks (CAN, FlexRay, Ethernet).\n</li></ul>\n</li><li><strong>Datenkonsistenz &amp; Nicht-Destruktivität:</strong>\n<ul class=\"fig-list\"><li>Da höherpriore Tasks den RAM-Test jederzeit unterbrechen können, dürfen die aktuell getesteten Speicherzellen nicht durch externe Zugriffe korrumpiert werden. \n</li><li>Der Treiber muss entweder nicht-destruktiv mit atomaren Schreib-/Lesezyklen und Zwischenpuffern arbeiten oder es dürfen nur solche RAM-Bereiche zur Laufzeit getestet werden, die während der Testphase gegen gleichzeitige Schreibzugriffe höherpriorer Tasks geschützt sind (Buffer Exclusion / Task Synchronisation).\n</li></ul>\n</li><li><strong>Gesamtumlaufzeit (RAM Coverage Cycle):</strong>\n<ul class=\"fig-list\"><li>Die Gesamtdauer für einen vollständigen Test des gesamten RAM-Bereichs berechnet sich aus:\n $$T_{\\text{Gesamttest}} = \\left\\lceil \\frac{\\text{Gesamtzahl zu prüfender Zellen}}{\\text{RamTstNumberOfTestedCells}} \\right\\rceil \\times T_{\\text{Task-Periode}}$$\n</li><li>Eine Reduktion der Blockgröße pro Aufruf zur Vermeidung von Task-Overruns verlängert unmittelbar die Diagnosezeit bis zur Fehlererkennung (Fault Detection Time Interval, FDTI nach ISO 26262).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-7a1380b50e53b244", "to": "FIG-aaa625bb82f04a03", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aaa625bb82f04a03", "to": "FIG-7f8a559327475c1a", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7f8a559327475c1a", "to": "FIG-67d8da68f53e0475", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Rahmen:</strong> Gesamte Grafik mit einer äußeren rechteckigen Rahmenlinie eingefasst.\n</li><li><strong>Aufruftrigger:</strong> Oberhalb der vertikalen Triggerpfeile wurde die Beschriftung von <code>Ramtst_MainFunction()</code> bzw. <code>RamTst_MainFunction()</code> um das Präfix <code>Scheduled task:</code> ergänzt.\n</li><li><strong>Zeitachse (t):</strong> Die horizontale Zeitachse ist an der rechten Pfeilspitze nun explizit mit <code>t</code> beschriftet.\n</li><li><strong>Untere Beschriftungen (vollständige Sichtbarkeit):</strong> Durch Erweiterung des Bildausschnitts nach unten sind die zuvor am Rand abgeschnittenen Beschriftungen vollständig lesbar:\n<ul class=\"fig-list\"><li>Mittleres Szenario: Vervollständigung von <code>Time needed to</code> zu <code>Time needed to complete one atomic test unit</code>.\n</li><li>Mittleres Szenario: Vervollständigung von <code>Example of time</code> zu <code>Example of time needed to complete a higher priority task</code>.\n</li><li>Rechtes Szenario: Vervollständigung von <code>Ramtst_MainFunction() is</code> zu <code>Ramtst_MainFunction() is entered, and is in “test running” state</code>.\n</li><li>Rechtes Szenario: Vervollständigung der Rückkehr-Annotation zu <code>Ramtst_MainFunction() returns, but stays in “test running” state until complete test is finished</code>.\n</li></ul>\n</li></ul>"}, {"from": "FIG-67d8da68f53e0475", "to": "FIG-1454d20ef35d834e", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Typografie &amp; Hyperlinks:</strong> Funktionsnamen (<code>RamTst_MainFunction()</code>), Statusangaben (<code>test running</code>) und Fachbegriffe (<code>task</code>) wurden mit blauer Unterstreichung im Hyperlink-Stil formatiert.\n</li><li><strong>Bildabmessungen:</strong> Leichte Skalierungs- und Randanpassung (Auflösung von 944x275 auf 902x264 Pixel geändert).\n</li></ul>"}]};
